<div class="panel mb-3"><h5>Tambah / Edit User</h5><form method="post" action="<?=site_url('users/save')?>" class="form-row"><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><input type="hidden" name="id" id="uid"><div class="col-md-3"><input class="form-control mb-2" name="name" id="uname" placeholder="Nama" required></div><div class="col-md-3"><input class="form-control mb-2" type="email" name="email" id="uemail" placeholder="Email" required></div><div class="col-md-2"><input class="form-control mb-2" type="password" name="password" placeholder="Password (wajib user baru)"></div><div class="col-md-2"><select class="form-control mb-2" name="role" id="urole"><option>staff</option><option>admin</option></select></div><div class="col-md-1"><select class="form-control mb-2" name="is_active"><option value="1">Aktif</option><option value="0">Nonaktif</option></select></div><div class="col-md-1"><button class="btn btn-pink">Save</button></div></form></div><div class="panel"><h5>Users</h5><?php foreach($rows as $u):?><div class="rank"><span><?=html_escape($u['name'])?> · <?=html_escape($u['email'])?> · <?=html_escape($u['role'])?></span><span><button class="btn btn-sm btn-outline-info" onclick='userEdit(<?=json_encode($u,JSON_HEX_APOS|JSON_HEX_QUOT)?>)'>Edit</button> <a class="btn btn-sm btn-outline-danger" href="<?=site_url('users/delete/'.$u['id'])?>" onclick="return confirm('Hapus user?')">Hapus</a></span></div><?php endforeach;?></div><script>function userEdit(u){uid.value=u.id;uname.value=u.name;uemail.value=u.email;urole.value=u.role;}</script>
